/* gm_sounds.h - sound asset table generated by tools/gen_sounds.py (indexed by GML sound id) */
#ifndef GM_SOUNDS_H
#define GM_SOUNDS_H
typedef struct gm_sounddef {
    const char *name;
    int kind;        /* -1 none, 0 SFX (resident in snd.bnk), 1 music (streamed from <name>.vas) */
    int off, len;    /* SFX: ADPCM body in snd.bnk */
    int rate;
    int dur_ms;
    float volume;    /* asset gain */
} gm_sounddef;
extern const gm_sounddef gm_sounds[];
extern const int gm_nsounds;
#endif
